 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        cells.add((ny, nx))
                        q.append((ny, nx))
            objects.append((color, cells))

    # Slide the rightmost objects first; every shape travels right until it
    # reaches the boundary or another shape.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    occupied = set()
    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        shift = 0
        while all(c + shift + 1 < w and (r, c + shift + 1) not in occupied
                  for r, c in cells):
            shift += 1
        moved = {(r, c + shift) for r, c in cells}
        for r, c in moved:
            out[r][c] = color
        occupied.update(moved)
    return out
